// ===== 計算エンジン =====
// マスター日次リターン r_d = (E_d − 入出金_d − E_{d−1}) / E_{d−1}
function masterSeries(){const m=all('SELECT date,equity,flow FROM master ORDER BY date');const out=[];for(let i=0;i<m.length;i++){const p=m[i-1];{let r=p?(m[i].equity-m[i].flow-p.equity)/p.equity:0;if(!isFinite(r)||Math.abs(r)>0.5)r=0;out.push({...m[i],r})}}return out}
// クライアント残高：開始日に軍資金 → 翌日以降 B=B×(1+r_d)+追加入金_d
function clientCalc(c,ms){ms=ms||masterSeries();const dep={};for(const d of all('SELECT date,amount FROM deposits WHERE client_id=?',[c.id]))dep[d.date]=(dep[d.date]||0)+d.amount;
 const bd=getS('base_date')||'';const s=ms.filter(x=>x.date>=c.start_date&&x.date>=bd);let B=null,inv=0,idx=1,peak=1,mdd=0;const ser=[];
 for(const x of s){if(B===null){B=c.capital+(dep[x.date]||0);inv=B}else{B=B*(1+x.r);idx*=1+x.r;if(dep[x.date]){B+=dep[x.date];inv+=dep[x.date]}}peak=Math.max(peak,idx);mdd=Math.max(mdd,1-idx/peak);ser.push({date:x.date,balance:B,share:B/x.equity,inv,dep:ser.length?(dep[x.date]||0):0})}
 if(B===null)return {ser:[],bal:c.capital,inv:c.capital,pnl:0,rate:0,twr:0,mdd:0,day:0,asof:c.start_date,pending:true};
 const last=ser[ser.length-1];return {ser,bal:B,inv,pnl:B-inv,rate:(B-inv)/inv,twr:idx-1,mdd,day:dd(c.start_date,last.date)+1,asof:last.date};}
function evFor(c){return c&&c.id?one("SELECT * FROM evidence WHERE kind='資産' AND public=1 AND client_id=? ORDER BY id DESC LIMIT 1",[c.id]):null}
function apiCard(){const ms=masterSeries(),L=ms[ms.length-1];const lt=getS('last_ts');const t=lt?new Date(Number(lt)+9*36e5).toISOString().slice(0,16).replace('T',' '):(L?L.date:'—');return `<div style="margin:12px 0 4px;padding:16px;border-radius:14px;background:linear-gradient(135deg,#123a2e,#0b2a20);border:1px solid #f7a60055;color:#eef5f1"><div style="font-size:11px;color:#a9c4b9;letter-spacing:.05em">Bybit 共有口座（APIで自動取得）</div><div style="font-size:26px;font-weight:800;margin:6px 0 0">${L?yen(L.equity):'—'}</div><div style="font-size:12px;color:#a9c4b9"></div><div style="display:flex;justify-content:space-between;margin-top:10px;font-size:12px"><span>前日比 <b style="color:${L&&L.r<0?'#ff6b6b':'#f7a600'}">${L?pct(L.r):'—'}</b></span><span style="color:#a9c4b9">取得：${t}</span></div></div>`}
function clientTrades(k){const sh={};k.ser.forEach((x,i)=>{sh[x.date]=i?k.ser[i-1].share:null});
 return all('SELECT * FROM trades ORDER BY ts DESC').map(t=>({...t,d:jst(t.ts)})).filter(t=>sh[t.d]).map(t=>({...t,cp:t.pnl*sh[t.d],cq:t.qty*sh[t.d]}))}
