async function bb(p,qs){const key=(getS('api_key')||'').trim(),sec=(getS('api_secret')||'').trim();if(!key||!sec)throw new Error('APIキーが登録されていません。共有口座設定でキーとシークレットを入れてください');const H=['https://api-demo.bybit.com','https://api.bybit.com'];const saved=getS('bybit_host');const order=saved&&H.includes(saved)?[saved,...H.filter(h=>h!=saved)]:H;let last=null;
 for(const host of order){const ts=Date.now().toString(),rw='10000';const sign=crypto.createHmac('sha256',sec).update(ts+key+rw+qs).digest('hex');let rs,tx;try{rs=await fetch(host+p+'?'+qs,{headers:{'X-BAPI-API-KEY':key,'X-BAPI-TIMESTAMP':ts,'X-BAPI-RECV-WINDOW':rw,'X-BAPI-SIGN':sign}});tx=await rs.text()}catch(e){last=new Error('Bybitにつながりませんでした。少し時間をおいてもう一度お試しください');continue}let j;try{j=JSON.parse(tx)}catch(e){console.error('bybit raw',host,rs.status,tx.slice(0,300));last=rs.status==401?new Error('APIキーが認識されませんでした。キーとシークレットを貼り直してください'):new Error('Bybitから正しい返事が来ませんでした（'+rs.status+'）'+(rs.status==403?'：サーバーの地域がBybitに制限されている可能性があります':''));continue}
  if(j.retCode===0){if(saved!=host)setS('bybit_host',host);return j.result}console.error('bybit',host,j.retCode,j.retMsg);
  if(j.retCode===10003||j.retCode===10004||j.retCode===33004){last=new Error(j.retCode===10004?'APIシークレットが合っていないようです。キーとシークレットを貼り直してください':j.retCode===33004?'APIキーの有効期限が切れています。Bybitで新しいキーを作って貼り直してください':'APIキーが認識されませんでした。キーとシークレットを貼り直してください');continue}
  if(j.retCode===10005)throw new Error('APIキーに必要な権限がありません。Bybitで「読み取り」権限をつけてください');if(j.retCode===10002)throw new Error('時刻のずれでBybitに断られました。もう一度お試しください');if(j.retCode===10010)throw new Error('このサーバーのIPアドレスがAPIキーで許可されていません。BybitのキーのIP制限を外してください');
  throw new Error('Bybitでエラーが出ました（コード '+j.retCode+'）。少し時間をおいてもう一度お試しください')}
 throw last||new Error('Bybitから残高を取得できませんでした')}
const TRADE_TYPES=['TRADE','SETTLEMENT','DELIVERY','LIQUIDATION','ADL','CURRENCY_BUY','CURRENCY_SELL','INTEREST','FEE_REFUND'];
async function fetchMaster(){const now=Date.now();const date=jst(now-36e5);// 0:05実行時は前日終値として記録
 const w=await bb('/v5/account/wallet-balance','accountType=UNIFIED');const eq=Number(w.list[0].totalEquity);
 // 入出金を取引ログから検出し、損益から除外
 const since=Number(getS('last_ts'))||now-7*864e5;let flow=0;
 try{const t=await bb('/v5/account/transaction-log',`accountType=UNIFIED&startTime=${since}&endTime=${now}&limit=50`);for(const x of t.list)if(!TRADE_TYPES.includes(x.type))flow+=Number(x.change)*(x.currency=='USDT'||x.currency=='USDC'?1:0)}catch(e){console.error('transaction-log',e.message)}
 const ex=one('SELECT flow FROM master WHERE date=?',[date]);db.run('INSERT OR REPLACE INTO master(date,equity,flow,source) VALUES(?,?,?,?)',[date,eq,(ex?ex.flow:0)+flow,'API']);
 const r=await bb('/v5/position/closed-pnl','category=linear&limit=100');for(const t of r.list)db.run('INSERT OR IGNORE INTO trades(oid,ts,symbol,side,qty,entry,exit,pnl) VALUES(?,?,?,?,?,?,?,?)',[t.orderId,Number(t.updatedTime),t.symbol,t.side=='Sell'?'ロング決済':'ショート決済',Number(t.closedSize),Number(t.avgEntryPrice),Number(t.avgExitPrice),Number(t.closedPnl)]);
 db.run("INSERT OR REPLACE INTO settings(k,v) VALUES('last_ts',?)",[String(now)]);save();return {eq,flow,date}}
