function terms(c,k){const principal=nz(c.principal,c.capital),add=nz(c.add_principal,k.inv-c.capital),patron=nz(c.patron,0),temp=principal+add+patron;
 return {principal,add,patron,temp,maturity:c.maturity_date||addY(c.start_date,1),feeRate:nz(c.fee_rate,20),tlo:nz(c.target_lo,3),thi:nz(c.target_hi,4)}}
