function parseCSV(t){t=t.replace(/^\ufeff/,'');const rows=[];for(const line of t.split(/\r?\n/)){if(!line.trim())continue;const c=[];let cur='',q=false;for(let i=0;i<line.length;i++){const ch=line[i];if(q){if(ch=='"'&&line[i+1]=='"'){cur+='"';i++}else if(ch=='"')q=false;else cur+=ch}else if(ch=='"')q=true;else if(ch==','){c.push(cur);cur=''}else cur+=ch}c.push(cur);rows.push(c.map(x=>x.trim()))}return rows}
const normDate=s=>{const m=String(s).match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})$/);if(!m)return null;const r=`${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;return (isNaN(new Date(r+'T00:00:00Z'))?'':new Date(r+'T00:00:00Z').toISOString()).slice(0,10)===r?r:null};
function checkRows(rows){if(rows[0]&&!normDate(rows[0][2]))rows=rows.slice(1);return rows.map((r,i)=>{const name=r[0],cap=Y2U(String(r[1]||'').replace(/[,円$\s]|USDT/g,'')),d=normDate(r[2]);const err=!name?'名前が空です':!(cap>0)?'軍資金が不正です':!d?'開始日が不正です（例：2026-10-01）':'';let err2='';const x=EXF.map((f,j)=>{const v=String(r[3+j]??'').trim();if(!v)return null;if(f[2]=='date'){const nd=normDate(v);if(!nd)err2=f[1].split('（')[0]+'が不正です';return nd}const n0=Number(v.replace(/[,円$%\s倍]|USDT/g,''));const n=['principal','add_principal','patron','temp_funds'].includes(f[0])?n0/fx():n0;if(!isFinite(n))err2=f[1].split('（')[0]+'が不正です';return n});const ex=name&&one('SELECT id FROM clients WHERE name=?',[name]);return {line:i+1,name,cap,d,x,err:err||err2,ex:!!ex}})}
